def execute(arguments):
    """
    单位转换

    参数:
        arguments (dict): 包含以下字段
            - value (float): 要转换的值，必填
            - from_unit (str): 源单位，必填
            - to_unit (str): 目标单位，必填
            - category (str): 单位类别，可选
                - "length": 长度 (m, km, cm, mm, mile, yard, foot, inch)
                - "weight": 重量 (kg, g, mg, lb, oz)
                - "temperature": 温度 (c, f, k)
                - "data": 数据存储 (b, kb, mb, gb, tb)
                - "time": 时间 (s, min, h, d, w, mo, y)

    返回:
        dict: 包含转换结果的字典
            - success (bool): 是否成功
            - result (float): 转换结果
            - value (float): 原始值
            - from_unit (str): 源单位
            - to_unit (str): 目标单位
            - error (str): 错误信息（失败时）
    """
    value = arguments.get("value")
    from_unit = arguments.get("from_unit", "").lower()
    to_unit = arguments.get("to_unit", "").lower()
    category = arguments.get("category", "")

    if value is None:
        return {"success": False, "error": "请提供要转换的值"}

    if not from_unit or not to_unit:
        return {"success": False, "error": "请提供源单位和目标单位"}

    conversions = {
        "length": {
            "m": 1, "km": 1000, "cm": 0.01, "mm": 0.001,
            "mile": 1609.344, "yard": 0.9144, "foot": 0.3048, "inch": 0.0254
        },
        "weight": {
            "kg": 1, "g": 0.001, "mg": 0.000001,
            "lb": 0.453592, "oz": 0.0283495
        },
        "data": {
            "b": 1, "kb": 1024, "mb": 1024**2, "gb": 1024**3, "tb": 1024**4
        },
        "time": {
            "s": 1, "min": 60, "h": 3600, "d": 86400, "w": 604800, "mo": 2592000, "y": 31536000
        }
    }

    try:
        if from_unit == to_unit:
            return {
                "success": True,
                "result": value,
                "value": value,
                "from_unit": from_unit,
                "to_unit": to_unit
            }

        if category == "temperature" or from_unit in ["c", "f", "k"]:
            if from_unit == "c" and to_unit == "f":
                result = value * 9/5 + 32
            elif from_unit == "c" and to_unit == "k":
                result = value + 273.15
            elif from_unit == "f" and to_unit == "c":
                result = (value - 32) * 5/9
            elif from_unit == "f" and to_unit == "k":
                result = (value - 32) * 5/9 + 273.15
            elif from_unit == "k" and to_unit == "c":
                result = value - 273.15
            elif from_unit == "k" and to_unit == "f":
                result = (value - 273.15) * 9/5 + 32
            else:
                return {"success": False, "error": f"不支持的温度单位转换: {from_unit} -> {to_unit}"}

            return {
                "success": True,
                "result": round(result, 4),
                "value": value,
                "from_unit": from_unit,
                "to_unit": to_unit
            }

        for cat, units in conversions.items():
            if from_unit in units and to_unit in units:
                base_value = value * units[from_unit]
                result = base_value / units[to_unit]
                return {
                    "success": True,
                    "result": round(result, 6),
                    "value": value,
                    "from_unit": from_unit,
                    "to_unit": to_unit,
                    "category": cat
                }

        return {"success": False, "error": f"不支持的单位转换: {from_unit} -> {to_unit}"}
    except Exception as e:
        return {"success": False, "error": f"转换失败: {str(e)}"}
